package com.bank.cycle.service;

import java.util.Arrays;
import java.util.logging.Logger;

// Best continuous stretch in a circular cash-flow cycle (may wrap around).
public class CyclicCashFlowAnalyzer {
    private static final Logger log = Logger.getLogger(CyclicCashFlowAnalyzer.class.getName());

    public long bestCyclicStretch(int[] flows) {
        if (flows == null || flows.length == 0) {
            throw new IllegalArgumentException("Flow cycle must be non-empty");
        }
        long total = 0;
        long curMax = flows[0], maxSum = flows[0];
        long curMin = flows[0], minSum = flows[0];
        total += flows[0];

        for (int i = 1; i < flows.length; i++) {
            int x = flows[i];
            total += x;
            curMax = Math.max(x, curMax + x);
            maxSum = Math.max(maxSum, curMax);
            curMin = Math.min(x, curMin + x);
            minSum = Math.min(minSum, curMin);
        }
        long answer;
        if (maxSum < 0) {
            // All-negative guard: wrapping would give empty subarray (invalid).
            answer = maxSum;
            log.fine(() -> "All-negative cycle; returning best single element");
        } else {
            answer = Math.max(maxSum, total - minSum);
        }
        final long a = answer, ms = maxSum, mn = minSum, t = total;
        log.info(() -> "Best cyclic stretch over " + Arrays.toString(flows)
                + " = max(maxSum " + ms + ", total " + t + " - minSum " + mn + ") = " + a);
        return answer;
    }
}
