package com.bank.cycle;

import com.bank.cycle.model.Account;
import com.bank.cycle.service.CyclicCashFlowAnalyzer;

import java.math.BigDecimal;
import java.util.Date;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class MaxCircularSubarrayDemo {
    private static final Logger log = Logger.getLogger(MaxCircularSubarrayDemo.class.getName());

    public static void main(String[] args) {
        setupLogging();
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        Account priya = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000"));

        CyclicCashFlowAnalyzer analyzer = new CyclicCashFlowAnalyzer();

        int[] rajeshCycle = {5, -3, 5}; // wrap: 5 (idx2) + 5 (idx0) = 10
        log.info(() -> rajesh.getHolderName() + " (" + rajesh.getAccountId() + ") cycle");
        long r1 = analyzer.bestCyclicStretch(rajeshCycle);
        log.info(() -> rajesh.getHolderName() + " best cyclic stretch = " + r1);

        int[] priyaCycle = {-2, -3, -1}; // all negative → -1 (least negative)
        log.info(() -> priya.getHolderName() + " (" + priya.getAccountId() + ") cycle");
        long r2 = analyzer.bestCyclicStretch(priyaCycle);
        log.info(() -> priya.getHolderName() + " best cyclic stretch = " + r2);
    }

    private static void setupLogging() {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.FINE);
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.FINE);
    }

    static class BankLogFormatter extends Formatter {
        @Override
        public String format(LogRecord r) {
            return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                    new Date(r.getMillis()), r.getLevel(), r.getMessage());
        }
    }
}
